import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.adminCarts().createAdminCart(Map.of(
        "customer_id", 512,
        "products", List.of(Map.of("product_id", 101, "quantity", 2))));
